#!/bin/sh
# GNU libiconv 1.17 library-only build for the legacy i386 CRT.
# Converter tables and aliases are generated by upstream host tools.
set -eu
cd "$(dirname "$0")"
. ./BUILDENV.SH
sh DEPPREP.SH
ic_prefix=${RP_CODEC_PREFIX:-/workspace/THRLIB}
ic_build=/workspace/ICBLD
mkdir -p "$ic_build" "$ic_prefix/include" "$ic_prefix/lib"
make -C /workspace/ICWORK -f Makefile.devel \
 include/iconv.h.build.in lib/aliases.h lib/aliases_aix.h \
 lib/aliases_osf1.h lib/aliases_dos.h lib/aliases_zos.h lib/aliases_extra.h \
 lib/flags.h lib/translit.h
python3 - <<'PY'
from pathlib import Path
src=Path('/workspace/ICWORK');out=Path('/workspace/ICBLD')
config='''/* Native little-endian Windows, CRTDLL, no locale multibyte APIs. */
#define WORDS_LITTLEENDIAN 1
#define ENABLE_EXTRA 1
#define ICONV_CONST
#define HAVE_WCHAR_T 1
#define HAVE_WCRTOMB 0
#define HAVE_MBRTOWC 0
#define HAVE_MBSINIT 0
#define HAVE_LANGINFO_CODESET 0
#define HAVE_VISIBILITY 0
#define ENABLE_RELOCATABLE 0
'''
(out/'config.h').write_text(config)
header=(src/'include/iconv.h.build.in').read_text()
for key,value in {'DLL_VARIABLE':'','EILSEQ':'42','ICONV_CONST':'',
                  'USE_MBSTATE_T':'0','BROKEN_WCHAR_H':'0','HAVE_WCHAR_T':'1',
                  'HAVE_VISIBILITY':'0'}.items():
    header=header.replace('@'+key+'@',value)
if '@' in header: raise SystemExit('Unexpanded iconv header configuration')
(out/'iconv.h').write_text(header)
(out/'localcharset.h').write_bytes((src/'libcharset/include/localcharset.h.in').read_bytes())
PY
ic_flags='-O2 -march=i386 -mno-sse -mno-sse2 -mno-mmx -fno-inline-atomics -mcrtdll=crtdll -D_WIN32_WINNT=0x0400 -DWINVER=0x0400'
./GCC386.SH $ic_flags -I"$ic_build" -I/workspace/ICWORK/lib \
 -c /workspace/ICWORK/lib/iconv.c -o "$ic_build/ICONV.O"
./GCC386.SH $ic_flags -I"$ic_build" -I/workspace/ICWORK/lib \
 -c /workspace/ICWORK/libcharset/lib/localcharset.c -o "$ic_build/CHARSET.O"
i686-w64-mingw32-ar rcs "$ic_build/libiconv.a" "$ic_build/ICONV.O" "$ic_build/CHARSET.O"
cp "$ic_build/iconv.h" "$ic_prefix/include/"
cp "$ic_build/libiconv.a" "$ic_prefix/lib/"
cp /workspace/ICWORK/COPYING.LIB LICENSES/ICONV.TXT
